function eval_gsn_basis_yc_sminus2!(out::Vector{ComplexF64}, coeffs::Vector{ComplexF64}, t::ComplexF64)
    return _evaluate_polynomial_blocks!(out,coeffs,t,(1:9,10:17,18:24,25:30,31:35,36:39,40:42,43:44,45:45,1:0,46:55,56:64,65:72,73:79,80:85,86:90,91:94,95:97,98:99,100:100,1:0,101:115,116:129,130:142,143:154,155:165,166:175,176:184,185:192,193:199,200:205,206:210,211:214,215:217,218:219,220:220,221:237,238:253,254:268,269:282,283:295,296:307,308:318,319:328,329:337,338:345,346:352,353:358,359:363,364:367,368:370,371:372,373:373,1:0,1:0,))
end

ordinary_value_count() = 55

function construct_gsn_basis(lambda, m, nu, omega)
    return construct_gsn_basis_yc_sminus2(lambda, m, nu, omega)
end

function eval_gsn_basis!(out::Vector{ComplexF64}, coeffs::Vector{ComplexF64}, x0)
    x0 = ComplexF64(x0)
    return eval_gsn_basis_yc_sminus2!(out, coeffs, 1.0 - x0)
end

function eval_gsn_basis_variable!(out::Vector{ComplexF64}, coeffs::Vector{ComplexF64}, value)
    return eval_gsn_basis_yc_sminus2!(out, coeffs, ComplexF64(value))
end

